/**
 * Which release, if any, a contract's on-chain code comes from — wherever that contract sits.
 *
 * A contract's runtime code embeds its immutables (the factory's wallet implementation, a UUPS
 * implementation's own address), so the same release leaves different bytes at different addresses.
 * Each release therefore publishes, per contract, a fingerprint: the keccak256 of the runtime code
 * with every immutable zeroed (release-fingerprints.ts, generated by `pnpm gen:releases`). Matching code against
 * a fingerprint proves which release it is; it says nothing about the immutables' values, which the
 * caller checks against the chain's own addresses (`factory.implementation()`, the paymaster
 * proxy's implementation slot).
 */
import { type Hex, keccak256 } from "viem";
import {
	RELEASE_FINGERPRINTS,
	type ReleaseContractName,
	type ReleaseFingerprint,
} from "./release-fingerprints";

export type {
	ReleaseContractName,
	ReleaseFingerprint,
} from "./release-fingerprints";
export { RELEASE_FINGERPRINTS } from "./release-fingerprints";

/** `code` with every range in `immutables` set to zero. `code` must be the fingerprint's size. */
export function maskImmutables(
	code: Hex,
	immutables: ReleaseFingerprint["immutables"],
): Hex {
	let masked = code.toLowerCase();
	for (const { start, length } of immutables) {
		const from = 2 + start * 2;
		masked =
			masked.slice(0, from) +
			"0".repeat(length * 2) +
			masked.slice(from + length * 2);
	}
	return masked as Hex;
}

/** The 32-byte word holding `address` as an immutable: left-padded to 32 bytes, lowercase, no 0x. */
function addressWord(address: Hex): string {
	return address.toLowerCase().slice(2).padStart(64, "0");
}

/**
 * The masked ranges themselves, which the fingerprint cannot see: every range of one immutable must
 * hold the same value (the factory reads `implementation` in several places, and code whose getter
 * returns one implementation while `createAccount` clones another is not release code), and, given
 * the address the code was read from, every UUPS `__self` range must hold that address. Code copied
 * from elsewhere, or with a modified `__self`, would make every UUPS upgrade revert.
 */
function immutablesConsistent(
	runtimeCode: Hex,
	immutables: ReleaseFingerprint["immutables"],
	address: Hex | undefined,
): boolean {
	const code = runtimeCode.toLowerCase();
	const values = new Map<string, string>();
	for (const { name, start, length } of immutables) {
		const value = code.slice(2 + start * 2, 2 + (start + length) * 2);
		const seen = values.get(name);
		if (seen !== undefined && seen !== value) return false;
		values.set(name, value);
		if (address && name.endsWith(".__self") && value !== addressWord(address))
			return false;
	}
	return true;
}

/**
 * Every release whose `contract` code `runtimeCode` is, oldest first; empty if none. Two releases
 * that leave a contract unchanged share its fingerprint, so code can be several releases' at once.
 * Compare against `eth_getCode` at the contract's address, not a creation code, and pass that
 * `address`: a UUPS implementation is then also checked to name itself in `__self`. Without it only
 * the masked hash and the consistency of each immutable's ranges are checked. `fingerprints` defaults
 * to every committed release's.
 */
export function releasesOf(
	contract: ReleaseContractName,
	runtimeCode: Hex,
	address?: Hex,
	fingerprints: readonly ReleaseFingerprint[] = RELEASE_FINGERPRINTS,
): ReleaseFingerprint[] {
	const size = (runtimeCode.length - 2) / 2;
	const hashes = new Map<string, Hex>();
	const matches: ReleaseFingerprint[] = [];
	for (const candidate of fingerprints) {
		if (candidate.contract !== contract || candidate.size !== size) continue;
		// Releases of one contract usually share a mask; hash each distinct one once.
		const key = candidate.immutables
			.map((i) => `${i.start}:${i.length}`)
			.join(",");
		let hash = hashes.get(key);
		if (!hash) {
			hash = keccak256(maskImmutables(runtimeCode, candidate.immutables));
			hashes.set(key, hash);
		}
		if (
			hash === candidate.fingerprint &&
			immutablesConsistent(runtimeCode, candidate.immutables, address)
		)
			matches.push(candidate);
	}
	return matches;
}

/**
 * The release whose `contract` code `runtimeCode` is, or undefined if it is no release's (see
 * releasesOf). When the code is several releases', `release` is returned if it is one of them —
 * pass the release you expect, so code a newer release left unchanged is not mistaken for an older
 * one — and otherwise the newest.
 */
export function releaseOf(
	contract: ReleaseContractName,
	runtimeCode: Hex,
	address?: Hex,
	release?: string,
): ReleaseFingerprint | undefined {
	const matches = releasesOf(contract, runtimeCode, address);
	return (
		(release !== undefined
			? matches.find((match) => match.release === release)
			: undefined) ?? matches.at(-1)
	);
}
